<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api,errorText } from '../api'
import { allowed,date,display,listItems } from '../domain'
import type { Row } from '../domain'
import { useAuth } from '../stores/auth'
import { useLoad } from '../composables'
import PageState from '../components/PageState.vue'
import { parseCalendarDates,validateCandidateWeights,validateTimeWindow,validateWorkingHours,previousShanghaiMonth } from '../workflowForms'

const auth=useAuth(),{loading,error,run}=useLoad()
const companyId=ref<string|number>(auth.me?.companyId??''),departments=ref<Row[]>([]),users=ref<Row[]>([]),policy=ref<Row>({}),tab=ref('compare'),period=ref(previousShanghaiMonth()),calendarId=ref<string|number>(0),templateId=ref<string|number>(0),reason=ref(''),deptId=ref<string|number>(''),result=ref<Row|null>(null),busy=ref(false),operationError=ref(''),drawer=ref(''),form=ref<Row>({}),formError=ref(''),taskOptions=ref<Row[]>([]),taskId=ref<string|number>(''),classification=ref<Row|null>(null),classificationReason=ref('')
const companies=computed(()=>{const map=new Map<string,Row>();if(auth.me?.companyId!=null)map.set(String(auth.me.companyId),{id:auth.me.companyId,name:'当前公司 '+auth.me.companyId});for(const d of departments.value){if(d.companyId!=null)map.set(String(d.companyId),{id:d.companyId,name:d.companyName||'公司 '+d.companyId})}return [...map.values()]})
const companyDepartments=computed(()=>departments.value.filter(d=>String(d.companyId)===String(companyId.value)))
const names=['按时完成率','逾期率','退回率','响应时长','执行时长']
function load(){if(companyId.value===''){error.value='请选择需要查看的公司';return}result.value=null;classification.value=null;taskId.value='';run(()=>api.get('/kpi/calendar-policy',{companyId:companyId.value}),v=>{policy.value=v;calendarId.value=0;templateId.value=0})}
function open(kind:string){formError.value='';drawer.value=kind;form.value={name:'',reason:'',expectedVersion:Math.max(0,...(policy.value.calendars??[]).map((c:Row)=>Number(c.version)||0)),mode:'WORKING_TIME',weekendDays:[0,6],dayStart:'09:00',dayEnd:'18:00',holidays:'',workingDates:'',leaves:[],weights:[30,25,20,10,15],complexityWeights:{SIMPLE:1,NORMAL:1,COMPLEX:1}}}
async function save(){if(busy.value)return;formError.value='';const f=form.value;if(!f.name?.trim()||!f.reason?.trim()){formError.value='请填写版本名称和变更原因';return}busy.value=true;try{let body:Row={companyId:companyId.value,name:f.name.trim(),reason:f.reason.trim()};if(drawer.value==='calendar'){const hours=validateWorkingHours(f.dayStart,f.dayEnd);if(hours)throw new Error(hours);const holidays=parseCalendarDates(f.holidays),workingDates=parseCalendarDates(f.workingDates);if(holidays.some(d=>workingDates.includes(d)))throw new Error('同一日期不能同时为节假日和补班日');for(const leave of f.leaves){const invalid=validateTimeWindow(leave.from,leave.to);if(invalid||!leave.to||!leave.deptId)throw new Error(invalid||'请补全请假记录的部门及结束时间')}body={...body,expectedVersion:f.expectedVersion,calendar:{mode:f.mode,weekendDays:f.weekendDays,dayStart:f.dayStart,dayEnd:f.dayEnd,holidays,workingDates,leaves:f.leaves.map((l:Row)=>({deptId:l.deptId,...(l.userId?{userId:l.userId}:{}),from:l.from,to:l.to}))}};await api.post('/kpi/calendar-versions',body)}else{const invalid=validateCandidateWeights(f.weights);if(invalid)throw new Error(invalid);body={...body,weights:f.weights,complexityWeights:f.complexityWeights,simulation:true};await api.post('/kpi/simulation-templates',body)}drawer.value='';ElMessage.success('候选版本已保存');load()}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
async function simulate(){if(busy.value)return;if(!reason.value.trim()||!period.value){operationError.value='请选择月份并填写模拟原因';return}busy.value=true;operationError.value='';try{result.value=await api.post('/kpi/calendar-simulations',{companyId:companyId.value,period:period.value,calendarVersionId:calendarId.value,templateId:templateId.value,simulation:true,reason:reason.value,...(deptId.value?{deptId:deptId.value}:{})});const updated=await api.get('/kpi/calendar-policy',{companyId:companyId.value});policy.value=updated;ElMessage.success('模拟完成，结果已冻结保存')}catch(e){operationError.value=errorText(e)}finally{busy.value=false}}
async function viewResult(id:string|number){busy.value=true;operationError.value='';try{result.value=await api.get(`/kpi/calendar-simulations/${id}`);tab.value='compare'}catch(e){operationError.value=errorText(e)}finally{busy.value=false}}
async function loadTasks(){try{taskOptions.value=listItems(await api.get('/tasks',{page:1,pageSize:100,companyId:companyId.value}))}catch(e){operationError.value=errorText(e)}}
async function loadClassification(){classification.value=null;classificationReason.value='';if(!taskId.value)return;try{classification.value=await api.get(`/tasks/${taskId.value}/classification`)}catch(e){operationError.value=errorText(e)}}
async function classify(){if(!classification.value||!allowed(classification.value,'classify'))return;if(!classificationReason.value.trim()){operationError.value='请填写分类调整原因';return}busy.value=true;try{classification.value=await api.post(`/tasks/${taskId.value}/classification`,{complexity:classification.value.complexity,category:classification.value.category,expectedVersion:classification.value.version??0,reason:classificationReason.value});classificationReason.value='';ElMessage.success('分类版本已保存，不追溯修改既有分数')}catch(e){operationError.value=errorText(e)}finally{busy.value=false}}
function score(value:unknown){return value==null?'N/A':display(value)}
onMounted(async()=>{try{const [d,u]=await Promise.all([api.get('/organization/departments'),api.get('/organization/users')]);departments.value=listItems(d);users.value=listItems(u);if(companyId.value===''&&companies.value.length)companyId.value=companies.value[0].id;load()}catch(e){error.value=errorText(e)}})
</script>
<template>
<section class="page-heading"><div><p class="eyebrow">CALENDAR & COMPLEXITY LAB</p><h1>日历与复杂度模拟</h1><p class="muted">以同一任务快照对比候选口径，保留可复算的分析记录。</p></div><el-button @click="load">刷新版本</el-button></section>
<div class="policy-banner"><b>仅用于模拟分析</b><span>正式权重仍为30 / 25 / 20 / 10 / 15；候选日历与复杂度策略不覆盖历史KPI。</span></div>
<el-alert v-if="operationError" :title="operationError" type="error" :closable="false"/>
<section class="panel">
<div class="filter-bar"><el-select v-model="companyId" placeholder="选择公司" aria-label="模拟公司" @change="load"><el-option v-for="c in companies" :key="c.id" :value="c.id" :label="c.name"/></el-select><span class="muted">默认复杂度：普通 · 默认类别：普通</span></div>
<PageState :loading="loading" :error="error" @retry="load">
<el-tabs v-model="tab" @tab-change="(value:string|number)=>{if(value==='classification')loadTasks()}">
<el-tab-pane label="模拟对比" name="compare">
<el-form v-if="allowed(policy,'simulate')" label-position="top" @submit.prevent="simulate"><div class="simulation-controls"><el-form-item label="考核月份" required><el-date-picker v-model="period" type="month" value-format="YYYY-MM" style="width:100%"/></el-form-item><el-form-item label="候选日历版本"><el-select v-model="calendarId"><el-option :value="0" label="原始自然时间口径"/><el-option v-for="c in policy.calendars||[]" :key="c.id" :value="c.id" :label="`${c.name} · v${c.version}`"/></el-select></el-form-item><el-form-item label="候选模板"><el-select v-model="templateId"><el-option :value="0" label="原兼容模板（30/25/20/10/15）"/><el-option v-for="t in policy.templates||[]" :key="t.id" :value="t.id" :label="`${t.name} · v${t.version}`"/></el-select></el-form-item><el-form-item label="分析部门（留空为授权范围）"><el-select v-model="deptId" clearable><el-option v-for="d in companyDepartments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item></div><el-form-item label="本次模拟原因" required><el-input v-model="reason" maxlength="1000" show-word-limit placeholder="说明比较目标，例如评估节假日与复杂任务的影响"/></el-form-item><el-button type="primary" native-type="submit" :loading="busy">运行并保存模拟</el-button></el-form>
<section v-if="result" class="simulation-result"><div class="panel-heading"><div><h2>冻结模拟结果 · #{{ result.id }}</h2><p class="muted">{{ result.period||period }} · 输入快照 {{ result.inputHash||'—' }}</p></div><span class="status">仅模拟</span></div><el-empty v-if="!result.rows?.length" description="本次范围内没有可计算的任务样本"/><article v-for="r in result.rows||[]" :key="r.deptId" class="simulation-row"><div class="row-between"><h3>{{ r.deptName||r.deptId }}</h3><span class="muted">样本 {{ r.sampleCount }} 项</span></div><div class="comparison-scores"><div><small>原始口径</small><strong>{{ score(r.baseline?.total) }}</strong></div><div><small>候选策略</small><strong>{{ score(r.candidate?.total) }}</strong></div><div><small>变化</small><strong :class="{'priority-high':Number(r.delta)<0}">{{ r.delta==null?'N/A':Number(r.delta)>0?'+'+r.delta:r.delta }}</strong></div></div><details><summary>查看指标分解与原始值</summary><div class="table-scroll"><table class="metric-comparison"><thead><tr><th>指标</th><th>原始指标分</th><th>候选指标分</th></tr></thead><tbody><tr v-for="(name,i) in names" :key="name"><td>{{ name }}</td><td>{{ score(r.baseline?.indicatorScores?.[i]) }}</td><td>{{ score(r.candidate?.indicatorScores?.[i]) }}</td></tr></tbody></table></div><p class="snapshot-data">原始值：{{ display(r.baseline?.metrics) }}</p><p class="snapshot-data">候选值：{{ display(r.candidate?.metrics) }}</p></details></article><div v-if="result.correlation" class="notice"><b>按时率与逾期率相关性</b><p>Pearson · 样本 {{ result.correlation.sampleCount }} · 系数 {{ score(result.correlation.coefficient) }}</p><p v-if="result.correlation.warning">{{ result.correlation.warning }}</p><small>相关性用于分析重复计分风险，不自动改变正式权重。</small></div></section>
<h2 class="saved-title">已保存的模拟</h2><el-empty v-if="!policy.simulations?.length" description="暂无模拟记录" :image-size="60"/><article v-for="s in policy.simulations||[]" :key="s.id" class="batch-row"><div><b>{{ s.period }} · 模拟 #{{ s.id }}</b><p class="muted">{{ date(s.createdAt) }} · {{ s.reason }}</p></div><el-button :loading="busy" @click="viewResult(s.id)">查看冻结结果</el-button></article>
</el-tab-pane>
<el-tab-pane label="日历版本" name="calendars"><div class="panel-heading"><p class="muted">版本只追加。请假排除仅按已授权部门显示，历史模拟保留原始输入。</p><el-button v-if="allowed(policy,'createCalendar')" type="primary" @click="open('calendar')">＋ 新增候选日历</el-button></div><el-empty v-if="!policy.calendars?.length" description="尚未登记候选日历，使用原自然时间口径"/><article v-for="c in policy.calendars||[]" :key="c.id" class="request-card"><div class="row-between"><h3>{{ c.name }} · v{{ c.version }}</h3><span class="status">冻结版本</span></div><p>{{ c.calendar?.mode==='WORKING_TIME'?'工作时段':'自然时间' }} · {{ c.calendar?.dayStart||'—' }}—{{ c.calendar?.dayEnd||'—' }}</p><p class="muted">节假日 {{ c.calendar?.holidays?.length??0 }} 天 · 补班日 {{ c.calendar?.workingDates?.length??0 }} 天 · 请假排除 {{ c.calendar?.leaves?.length??0 }} 条</p><p class="pre-wrap">{{ c.reason }}</p></article></el-tab-pane>
<el-tab-pane label="候选模板" name="templates"><div class="panel-heading"><p class="muted">候选模板只提供对比分析，不具有发布正式考核的入口。</p><el-button v-if="allowed(policy,'createTemplate')" type="primary" @click="open('template')">＋ 新增候选模板</el-button></div><el-empty v-if="!policy.templates?.length" description="暂无候选模板，沿用原兼容权重"/><article v-for="t in policy.templates||[]" :key="t.id" class="request-card"><div class="row-between"><h3>{{ t.name }} · v{{ t.version }}</h3><span class="status">仅模拟</span></div><p>五项指标权重 {{ display(t.weights) }}</p><p>复杂度系数 {{ display(t.complexityWeights) }}</p><p class="muted">{{ t.reason }}</p></article></el-tab-pane>
<el-tab-pane label="任务分类" name="classification"><p class="notice">任务默认“普通复杂度 / 普通类别”。分类调整追加版本，不追溯改变冻结分数。</p><el-form label-position="top" @submit.prevent="classify"><el-form-item label="选择授权任务"><el-select v-model="taskId" filterable clearable @change="loadClassification"><el-option v-for="t in taskOptions" :key="t.id" :value="t.id" :label="`${t.code} · ${t.title}`"/></el-select></el-form-item><template v-if="classification"><div class="form-grid"><el-form-item label="复杂度"><el-select v-model="classification.complexity" :disabled="!allowed(classification,'classify')"><el-option label="简单" value="SIMPLE"/><el-option label="普通" value="NORMAL"/><el-option label="复杂" value="COMPLEX"/></el-select></el-form-item><el-form-item label="任务类别"><el-input v-model="classification.category" maxlength="50" :disabled="!allowed(classification,'classify')"/></el-form-item></div><p class="muted">当前分类版本 {{ classification.version??0 }}</p><el-form-item v-if="allowed(classification,'classify')" label="调整原因" required><el-input v-model="classificationReason" maxlength="1000" type="textarea"/></el-form-item><el-button v-if="allowed(classification,'classify')" type="primary" native-type="submit" :loading="busy">追加分类版本</el-button></template></el-form></el-tab-pane>
</el-tabs>
</PageState>
</section>
<el-drawer :model-value="!!drawer" :title="drawer==='calendar'?'新增候选日历版本':'新增候选模拟模板'" size="720px" :close-on-click-modal="false" @update:model-value="(value:boolean)=>{if(!value)drawer=''}"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="save"><el-form-item label="版本名称" required><el-input v-model="form.name" maxlength="100"/></el-form-item><template v-if="drawer==='calendar'"><el-form-item label="计时口径"><el-radio-group v-model="form.mode"><el-radio value="WORKING_TIME">工作时段</el-radio><el-radio value="NATURAL_TIME">自然时间</el-radio></el-radio-group></el-form-item><el-form-item label="每周休息日"><el-checkbox-group v-model="form.weekendDays"><el-checkbox v-for="(day,i) in ['日','一','二','三','四','五','六']" :key="i" :value="i">周{{ day }}</el-checkbox></el-checkbox-group></el-form-item><div class="form-grid"><el-form-item label="工作开始时间"><el-input v-model="form.dayStart" type="time"/></el-form-item><el-form-item label="工作结束时间"><el-input v-model="form.dayEnd" type="time"/></el-form-item></div><el-form-item label="节假日（YYYY-MM-DD，逗号或换行分隔）"><el-input v-model="form.holidays" type="textarea" :rows="3"/></el-form-item><el-form-item label="补班日期（优先于周休息日）"><el-input v-model="form.workingDates" type="textarea" :rows="3"/></el-form-item><h3>请假排除时段</h3><article v-for="(leave,i) in form.leaves" :key="i" class="scope-editor"><el-form-item label="所属部门" required><el-select v-model="leave.deptId"><el-option v-for="d in companyDepartments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="人员（可选，留空为部门）"><el-select v-model="leave.userId" clearable filterable><el-option v-for="u in users" :key="u.id" :value="u.id" :label="u.name"/></el-select></el-form-item><el-form-item label="开始 / 结束" required><el-date-picker v-model="leave.from" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" style="width:100%"/><el-date-picker v-model="leave.to" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" style="width:100%;margin-top:10px"/></el-form-item><el-button text type="danger" @click="form.leaves.splice(i,1)">移除此时段</el-button></article><el-button @click="form.leaves.push({deptId:'',userId:'',from:'',to:''})">＋ 添加请假时段</el-button></template><template v-else-if="drawer==='template'"><h3>五项指标权重（合计100）</h3><div class="form-grid"><el-form-item v-for="(name,i) in names" :key="name" :label="name"><el-input-number v-model="form.weights[i]" :min="0" :max="100" :precision="2"/></el-form-item></div><h3>复杂度系数</h3><p class="muted">普通固定为1；简单、复杂的候选系数范围0.25至4。</p><div class="form-grid"><el-form-item v-for="(name,key) in {SIMPLE:'简单',NORMAL:'普通',COMPLEX:'复杂'}" :key="key" :label="name"><el-input-number v-model="form.complexityWeights[key]" :min="0.25" :max="4" :step="0.25" :disabled="key==='NORMAL'"/></el-form-item></div></template><el-form-item label="新增原因" required><el-input v-model="form.reason" type="textarea" :rows="3" maxlength="1000" show-word-limit/></el-form-item><p class="scope-note">保存后追加候选版本，正式历史不变。当前基于版本 {{ form.expectedVersion??0 }}。</p><div class="form-footer"><el-button @click="drawer=''">返回</el-button><el-button type="primary" native-type="submit" :loading="busy">保存候选版本</el-button></div></el-form></el-drawer>
</template>
<style scoped>
.simulation-controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px}.simulation-result{border-top:1px solid var(--line);margin-top:28px;padding-top:24px}.simulation-row{border:1px solid var(--line);padding:20px;border-radius:6px;margin-bottom:16px}.comparison-scores{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:16px 0}.comparison-scores>div{background:var(--surface-muted);border-radius:4px;padding:14px}.comparison-scores small{color:var(--muted);font-size:11px;display:block}.comparison-scores strong{display:block;font-size:25px;color:var(--brand);margin-top:5px}.comparison-scores .priority-high{color:var(--danger)}.metric-comparison{width:100%;border-collapse:collapse;margin:14px 0;font-size:12px;text-align:left}.metric-comparison th,.metric-comparison td{border-bottom:1px solid var(--line);padding:10px}.snapshot-data{font-size:11px;color:var(--muted);overflow-wrap:anywhere;margin:10px 0}.saved-title{margin-top:30px}.simulation-row summary{font-size:12px;color:var(--brand);cursor:pointer}.simulation-result .notice p{margin:8px 0}.el-form-item .el-date-editor{max-width:100%}@media(max-width:767px){.simulation-controls{grid-template-columns:minmax(0,1fr)}.comparison-scores{gap:7px}.comparison-scores>div{padding:10px}.comparison-scores strong{font-size:20px}.simulation-row{padding:15px}.panel-heading{flex-wrap:wrap}.simulation-result .panel-heading p{overflow-wrap:anywhere}.simulation-row .row-between{flex-wrap:wrap}}
</style>
